[
  {
    "title": "prefight-reference-access",
    "claim": "Image #2 shows the qualifier instructions and Fight button without a visible Moves control, whereas Image #3 includes Moves.",
    "reason": "New players need the command reference alongside the introductory instructions.",
    "suggest": "Add a Techniques button beside Fight that opens the existing reference screen."
  },
  {
    "title": "countdown-reading-pressure",
    "claim": "Image #2 displays STARTING IN 7 beneath Fight while presenting instructions, and Image #8 displays STARTING IN 8 beneath Rematch.",
    "reason": "The wording signals a deadline for reading instructions or reviewing results; these stills cannot establish what happens when the countdown expires.",
    "suggest": "Make these decision screens player-paced and remove the countdown text; first capture countdown expiry to determine whether this requires a logic change or only a copy change."
  },
  {
    "title": "technique-hint-mapping",
    "claim": "Image #3 labels the technique directions back, forward, up and down, while Image #6 additionally identifies their meanings as reverse, punch, kick and sweep.",
    "reason": "The in-fight hint omits the action mapping that the reference provides, making beginners memorize it.",
    "suggest": "Use Forward: punch, Back: reverse, Up: kick and Down: sweep in the technique hint, wrapping the labels rather than shrinking them."
  },
  {
    "title": "point-call-explanation",
    "claim": "The IPPON banner in Image #17 and WAZA-ARI banner in Image #20 identify the fighter and technique but do not explicitly state the awarded point value.",
    "reason": "Players unfamiliar with the terminology must consult the scoreboard or reference to understand the call.",
    "suggest": "Add Full point or Half point to the banner, derived from the actual scoring event, while retaining the Japanese call."
  },
  {
    "title": "settings-backdrop-cutoff",
    "claim": "In Images #7 and #16, the opaque settings surface ends partway down the screen, hiding the fighters' upper bodies while leaving their lower bodies visible beneath it.",
    "reason": "The abrupt partial reveal distracts from the settings and makes the overlay feel visually unfinished.",
    "suggest": "Extend the opaque settings surface to the full viewport height, with scrollable content and a persistently available Close control."
  }
]
